210	        HttpHeaders headers = new HttpHeaders();
211	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
212	        applyAddress(owner, ownerFieldsDto);
213	        rejectFutureRegistrationDate(owner.getRegistrationDate());
214	        LocalDate effectiveDate = owner.getRegistrationDate() == null
215	            ? LocalDate.now()
216	            : owner.getRegistrationDate();
217	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
218	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
219	        rejectWhenCityAtCapacity(owner.getCity());
220	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
221	        applyHousehold(owner);
222	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
223	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
224	        rejectDuplicateIdentity(owner);
225	        owner.setMemberId(memberId(owner));
226	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
227	        flagPossibleDuplicate(owner, sharesHousehold);
228	        this.clinicService.saveOwner(owner);
229	        if (idempotencyKey != null) {
230	            ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
231	        }
232	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
233	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
234	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
235	            ownerDto.getMembershipLevel());
236	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
237	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
238	        AUDIT.info("{}", event.toJson());
239	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
