260	    /**
261	     * Returns the owner's current primary identifier, the value carried by the {@link OwnerCreatedEvent}
262	     * so downstream consumers can key the create off the owner's canonical identity. An owner's primary
263	     * identifier is its unified {@code memberId}, and the emitted event follows automatically.
264	     *
265	     * @param owner the freshly created owner, with its identifiers already assigned
266	     * @return the owner's current primary identifier
267	     */
268	    private String primaryIdentifier(Owner owner) {
