272	    /**
273	     * Builds the owner's unified member id, formatted {@code <REGION><FY><HASH8><CHK>}: REGION is the
274	     * region code derived from the owner's postcode (falling back to the city-to-region table, then
275	     * {@code UNKNOWN}); FY is the 2-digit fiscal year of the owner's business-day-adjusted registration
276	     * date; HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the owner's normalized
277	     * telephone concatenated with its last name; and CHK is a single Luhn check digit computed over the
278	     * digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D3}).
279	     *
280	     * <p>Should the computed member id collide with an existing owner's {@code memberId}, it is
281	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
282	     * unique (e.g. {@code NSW261A2B3C4D3-2}), so distinct owners always receive distinct member ids.
283	     *
284	     * @param owner the owner being created, with its normalized telephone and business-day-adjusted
285	     *              registration date already applied
286	     * @return the assigned, de-duplicated member id
287	     */
288	    private String memberId(Owner owner) {
289	        String core = regionCode(owner)
290	            + String.format("%02d", fiscalYear(owner.getRegistrationDate()) % 100)
291	            + identityHash8(owner.getTelephone(), owner.getLastName());
292	        String base = core + luhnCheckDigit(core);
293	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
294	            .map(Owner::getMemberId)
295	            .filter(id -> id != null)
296	            .collect(java.util.stream.Collectors.toSet());
297	        if (!existingIds.contains(base)) {
298	            return base;
299	        }
300	        int n = 2;
301	        while (existingIds.contains(base + "-" + n)) {
302	            n++;
303	        }
304	        return base + "-" + n;
305	    }
306	
307	    /**
308	     * Computes the Luhn check digit (a single digit 0-9) over the digits contained in the given value.
309	     * Non-digit characters are ignored.
310	     *
311	     * @param value the value whose digits the check digit is computed over
312	     * @return the Luhn check digit
313	     */
314	    private int luhnCheckDigit(String value) {
315	        int sum = 0;
316	        boolean dbl = true;
317	        for (int i = value.length() - 1; i >= 0; i--) {
318	            char c = value.charAt(i);
319	            if (c < '0' || c > '9') {
320	                continue;
321	            }
322	            int d = c - '0';
323	            if (dbl) {
324	                d *= 2;
325	                if (d > 9) {
326	                    d -= 9;
327	                }
328	            }
329	            sum += d;
330	            dbl = !dbl;
331	        }
332	        return (10 - (sum % 10)) % 10;
333	    }
