335	    /**
336	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
337	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
338	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
339	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
340	     * postcode nor the city identifies a region.
341	     *
342	     * @param owner the owner being created
343	     * @return the derived region code, never {@code null}
344	     */
345	    private String regionCode(Owner owner) {
346	        String fromPostcode = regionFromPostcode(owner.getPostcode());
347	        if (fromPostcode != null) {
348	            return fromPostcode;
349	        }
350	        String fromCity = region(owner.getCity());
351	        return fromCity == null ? "UNKNOWN" : fromCity;
352	    }
353	
354	    /**
355	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
356	     * postcode is absent, not 4 digits, or in no known range.
357	     *
358	     * @param postcode the owner's postcode, may be {@code null}
359	     * @return the region code, or {@code null} when no known range contains the postcode
360	     */
361	    private String regionFromPostcode(String postcode) {
362	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
363	            return null;
364	        }
365	        int value = Integer.parseInt(postcode);
366	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
367	            int[] range = entry.getValue();
368	            if (value >= range[0] && value <= range[1]) {
369	                return entry.getKey();
370	            }
371	        }
372	        return null;
373	    }
374	
375	    /**
376	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
377	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
378	     *
379	     * @param telephone the owner's normalized (E.164) telephone
380	     * @param lastName  the owner's last name
381	     * @return the 8-character upper-cased hex hash
382	     */
383	    private String identityHash8(String telephone, String lastName) {
384	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
385	        try {
386	            byte[] digest = MessageDigest.getInstance("SHA-256")
387	                .digest(input.getBytes(StandardCharsets.UTF_8));
388	            StringBuilder hex = new StringBuilder(digest.length * 2);
389	            for (byte b : digest) {
390	                hex.append(String.format("%02x", b));
391	            }
392	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
393	        } catch (NoSuchAlgorithmException ex) {
394	            throw new IllegalStateException("SHA-256 not available", ex);
395	        }
396	    }
