403	    /**
404	     * Derives the fiscal year of the given date. The fiscal year starts on 1 July, so a date on or
405	     * after 1 July belongs to the following calendar year's fiscal year (e.g. 2026-07-01 is fiscal
406	     * year 2027) while an earlier date takes the calendar year unchanged.
407	     *
408	     * @param date the date to derive the fiscal year of
409	     * @return the fiscal year
410	     */
411	    private int fiscalYear(LocalDate date) {
412	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
413	    }
