415	    /**
416	     * Counts the existing owners that already share the given firstName and lastName, compared
417	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
418	     * the owners that pre-existed this create.
419	     *
420	     * @param firstName the new owner's first name
421	     * @param lastName  the new owner's last name
422	     * @return the number of existing namesakes
423	     */
424	    private int countNamesakes(String firstName, String lastName) {
425	        return (int) this.clinicService.findAllOwners().stream()
426	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
