431	    /**
432	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
433	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
434	     * still resemble an existing owner: when it shares an existing owner's {@code soundex(lastName)}
435	     * and postcode while deriving a different identityKey, the owner is flagged with
436	     * {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing owner's id.
437	     * When no such owner exists the flag is set to {@code false} and no match id is recorded. An
438	     * owner with no postcode can never soft-match and is always {@code false}.
439	     *
440	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
441	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
442	     * always flagged {@code false}.
443	     *
444	     * @param owner           the owner being created, with its normalized telephone already applied
445	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
446	     *                        never flagged as a possible duplicate
447	     */
448	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
449	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
450	        if (match != null) {
451	            owner.setPossibleDuplicate(true);
452	            owner.setPossibleDuplicateOf(match.getId());
453	        } else {
454	            owner.setPossibleDuplicate(false);
455	            owner.setPossibleDuplicateOf(null);
456	        }
457	    }
458	
459	    /**
460	     * Finds the existing owner this owner soft-matches: a different {@link #identityKey(Owner)
461	     * identityKey} but the same {@code soundex(lastName)} and the same postcode. Because the
462	     * telephone now feeds the identityKey, two owners sharing a lastName and postcode with different
463	     * telephones have different keys and so soft-match here rather than being rejected as a hard
464	     * duplicate. When several existing owners match, the one with the lowest id is chosen so the
465	     * result is deterministic. Returns {@code null} when the owner has no postcode or no such
466	     * existing owner exists.
467	     *
468	     * @param owner the owner being created
469	     * @return the matching existing owner, or {@code null} when there is no soft-match
470	     */
471	    private Owner findPossibleDuplicate(Owner owner) {
472	        if (isBlank(owner.getPostcode())) {
473	            return null;
474	        }
475	        String identityKey = identityKey(owner);
476	        String soundex = IdentityKeys.soundex(owner.getLastName());
477	        return this.clinicService.findAllOwners().stream()
478	            .filter(existing -> !identityKey.equals(identityKey(existing))
479	                && soundex.equals(IdentityKeys.soundex(existing.getLastName()))
480	                && owner.getPostcode().equals(existing.getPostcode()))
481	            .min(Comparator.comparing(Owner::getId))
482	            .orElse(null);
483	    }
