485	    /**
486	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
487	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
488	     * customer-code sequence is derived.
489	     *
490	     * @param city the new owner's city
491	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
492	     */
493	    private void rejectWhenCityAtCapacity(String city) {
494	        long count = this.clinicService.findAllOwners().stream()
495	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
496	            .count();
497	        if (count >= CITY_CAPACITY) {
498	            throw new CityAtCapacityException(city);
499	        }
500	    }
