502	    /**
503	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
504	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
505	     * business-day registration date, so the limit is enforced per business day and weekend
506	     * requests count against the Monday they roll forward to.
507	     *
508	     * @param registrationDate the owner's adjusted (business-day) registration date
509	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
510	     *                                  registration date
511	     */
512	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
513	        long count = this.clinicService.findAllOwners().stream()
514	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
515	            .count();
516	        if (count >= DAILY_OWNER_LIMIT) {
517	            throw new DailyOwnerLimitException(registrationDate);
518	        }
519	    }
