521	    /**
522	     * Rejects creating an owner whose supplied {@code registrationDate} lies in the future, i.e. is
523	     * later than the current server date. A {@code null} registration date is accepted (it defaults
524	     * to the server date) and today or any past date is allowed; only a future value is rejected.
525	     *
526	     * @param registrationDate the registration date supplied on the request, may be {@code null}
527	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
528	     */
529	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
530	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
531	            throw new FutureRegistrationDateException(registrationDate);
532	        }
533	    }
534	
535	    /**
536	     * Rolls a registration date forward onto a business day: while it falls on a Saturday, a Sunday or
537	     * a listed {@link #PUBLIC_HOLIDAYS public holiday} it advances one day at a time until it lands on
538	     * a non-holiday weekday, otherwise it is returned unchanged. Applied to the effective registration
539	     * date (whether supplied in the request or defaulted to the server date) so a weekend or holiday
540	     * value never persists as an owner's {@code registrationDate}.
541	     *
542	     * @param date the effective registration date
543	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
544	     */
545	    private LocalDate toBusinessDay(LocalDate date) {
546	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
547	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
548	            || PUBLIC_HOLIDAYS.contains(date)) {
549	            date = date.plusDays(1);
550	        }
551	        return date;
552	    }
