570	    /**
571	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
572	     * offending field so the client learns about all of them at once.
573	     *
574	     * <p>An address may be supplied in either form: the structured {@code addressLine1} or the flat
575	     * {@code address}. The {@code address} error is raised only when both are missing or blank, so a
576	     * structured owner (with {@code addressLine1}) and an earlier flat owner (with {@code address})
577	     * are both accepted.
578	     *
579	     * @param ownerFieldsDto the submitted owner fields
580	     * @throws MissingOwnerFieldsException if firstName, lastName, address (in either form), city or
581	     *                                     telephone is missing or blank
582	     */
583	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
584	        List<String> errors = new ArrayList<>();
585	        if (isBlank(ownerFieldsDto.getFirstName())) {
586	            errors.add("firstName");
587	        }
588	        if (isBlank(ownerFieldsDto.getLastName())) {
589	            errors.add("lastName");
590	        }
591	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddressLine1()))
592	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
593	            errors.add("address");
594	        }
595	        if (isBlank(ownerFieldsDto.getCity())) {
596	            errors.add("city");
597	        }
598	        if (isBlank(ownerFieldsDto.getTelephone())) {
599	            errors.add("telephone");
600	        }
601	        if (!errors.isEmpty()) {
602	            throw new MissingOwnerFieldsException(errors);
603	        }
604	    }
605	
606	    private boolean isBlank(String value) {
607	        return value == null || value.isBlank();
608	    }
609	
610	    /**
611	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
612	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
613	     */
614	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
615	        "NSW", new int[] {2000, 2099},
616	        "VIC", new int[] {3000, 3099},
617	        "QLD", new int[] {4000, 4099});
618	
619	    /**
620	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
621	     * is optional and accepted, keeping the create contract backward-compatible. When present the
622	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
623	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
624	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
625	     *
626	     * @param postcode the raw postcode value as submitted, may be {@code null}
627	     * @param city     the owner's city, used to resolve the region whose range applies
628	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
629	     *                                  the city's region
630	     */
631	    private void validatePostcode(String postcode, String city) {
632	        if (isBlank(postcode)) {
633	            return;
634	        }
635	        if (!postcode.matches("[0-9]{4}")) {
636	            throw new InvalidPostcodeException(postcode, city);
637	        }
638	        String region = region(city);
639	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
640	        if (range != null) {
641	            int value = Integer.parseInt(postcode);
642	            if (value < range[0] || value > range[1]) {
643	                throw new InvalidPostcodeException(postcode, city);
644	            }
645	        }
646	    }
647	
648	    /**
649	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
650	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
651	     *
652	     * @param city the owner's city
653	     * @return the region code, or {@code null} when the city has no known region
654	     */
655	    private String region(String city) {
656	        if (city == null) {
657	            return null;
658	        }
659	        return switch (city) {
660	            case "Sydney" -> "NSW";
661	            case "Melbourne" -> "VIC";
662	            case "Brisbane" -> "QLD";
663	            default -> null;
664	        };
665	    }
666	
667	    /**
668	     * The number of national (subscriber) digits an E.164 number must carry for a given country
669	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
670	     * national digits and the North American Numbering Plan ('+1') requires 10.
671	     */
672	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
673	        Map.of("61", 9, "1", 10);
674	
675	    /**
676	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
677	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
678	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
679	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
680	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
681	     *
682	     * @param telephone the raw telephone value as submitted
683	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
684	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
685	     *                                   national-number length is wrong for its country code
686	     */
687	    private String normalizeTelephone(String telephone) {
688	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
689	        String nationalSignificantNumber;
690	        if (cleaned.startsWith("+")) {
691	            nationalSignificantNumber = cleaned.substring(1);
692	        } else {
693	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
694	            nationalSignificantNumber = "61" + national;
695	        }
696	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
697	            throw new InvalidTelephoneException(telephone);
698	        }
699	        validateNationalNumberLength(nationalSignificantNumber, telephone);
700	        return "+" + nationalSignificantNumber;
701	    }
702	
703	    /**
704	     * Validates the national-number length of an E.164 number against its country calling code. The
705	     * significant number is a country code immediately followed by the national digits; for each
706	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
707	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
708	     * left unchecked.
709	     *
710	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
711	     * @param rejectedValue             the raw telephone value, reported on rejection
712	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
713	     */
714	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
715	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
716	            String countryCode = rule.getKey();
717	            if (nationalSignificantNumber.startsWith(countryCode)) {
718	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
719	                if (nationalDigits != rule.getValue()) {
720	                    throw new InvalidTelephoneException(rejectedValue);
721	                }
722	                return;
723	            }
724	        }
725	    }
726	
727	    /**
728	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
729	     * value is treated as absent and returns {@code null}); when present the value must be a
730	     * syntactically valid address, and is stored and returned lower-cased.
731	     *
732	     * @param email the raw email value as submitted, may be {@code null}
733	     * @return the lower-cased email, or {@code null} when none was supplied
734	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
735	     */
736	    private String normalizeEmail(String email) {
737	        if (email == null || email.isBlank()) {
738	            return null;
739	        }
740	        String normalized = email.trim().toLowerCase();
741	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
742	            throw new InvalidEmailException(email);
743	        }
744	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
745	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
746	            throw new DisposableEmailException(email);
747	        }
748	        return normalized;
749	    }
750	
751	    /**
752	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
753	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing, non-deleted owner.
754	     * Because the key is the SHA-256 of the normalized telephone, lower-cased email and
755	     * {@code soundex(lastName)} joined together, this one check is the sole duplicate rule: only an
756	     * exact full-key match counts as a duplicate, so two owners sharing a lastName and postcode but
757	     * carrying different telephones have different keys and are both allowed (the second is instead
758	     * flagged a soft match).
759	     *
760	     * @param owner the owner being created, with its normalized telephone and email already applied
761	     * @throws DuplicateIdentityException if another owner already has the same identityKey
762	     */
763	    private void rejectDuplicateIdentity(Owner owner) {
764	        String identityKey = identityKey(owner);
765	        boolean inUse = this.clinicService.findAllOwners().stream()
766	            .filter(existing -> !isDeleted(existing))
767	            .map(this::identityKey)
768	            .anyMatch(identityKey::equals);
769	        if (inUse) {
770	            throw new DuplicateIdentityException(identityKey);
771	        }
772	    }
773	
774	    /**
775	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 of
776	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A {@code null}
777	     * telephone or email contributes an empty segment. Every duplicate decision is made by comparing
778	     * whole identityKeys.
779	     *
780	     * @param owner the owner whose identityKey to derive
781	     * @return the derived identityKey
782	     */
783	    private String identityKey(Owner owner) {
784	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
785	    }
786	
787	    /**
788	     * Applies the household rule to an owner being created. The household is keyed on
789	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
790	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
791	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
792	     *
793	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
794	     * same householdId is a member of the same household. A new owner sharing an existing household
795	     * is admitted as a further member of it — its membership level is then capped by the household
796	     * (see {@code OwnerMapper#membershipLevel}) rather than the create being rejected.
797	     *
798	     * @param owner the owner being created
799	     */
800	    private void applyHousehold(Owner owner) {
801	        owner.setHouseholdId(householdId(owner));
802	    }
803	
804	    /**
805	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
806	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
807	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
808	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
809	     * creation order. A {@code null} postcode contributes an empty segment.
810	     *
811	     * @param owner the owner whose household identifier to derive
812	     * @return the household identifier
813	     */
814	    private String householdId(Owner owner) {
815	        String lastNameKey = toHouseholdKey(owner.getLastName());
816	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
817	        try {
818	            byte[] digest = MessageDigest.getInstance("SHA-256")
819	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
820	            StringBuilder hex = new StringBuilder(digest.length * 2);
821	            for (byte b : digest) {
822	                hex.append(String.format("%02x", b));
823	            }
824	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
825	        } catch (NoSuchAlgorithmException ex) {
826	            throw new IllegalStateException("SHA-256 not available", ex);
827	        }
828	    }
829	
830	    /**
831	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
832	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
833	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
834	     * string.
835	     */
836	    private String toHouseholdKey(String value) {
837	        if (value == null) {
838	            return "";
839	        }
840	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
841	    }
842	
843	    /**
844	     * Applies the owner's address, preferring the structured form over the flat one. The structured
845	     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
846	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
847	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
848	     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
849	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
850	     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
851	     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
852	     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
853	     * address therefore sees the structured value when present, falling back to the flat one.
854	     *
855	     * @param owner the owner being created
856	     * @param dto   the submitted owner fields
857	     */
858	    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
859	        String line1 = normalizeAddress(dto.getAddressLine1());
860	        String line2 = normalizeAddress(dto.getAddressLine2());
861	        String flat = normalizeAddress(dto.getAddress());
862	        String effectiveLine1 = line1.isEmpty() ? flat : line1;
863	        String effectiveLine2 = line1.isEmpty() ? "" : line2;
864	        String composed = effectiveLine2.isEmpty()
865	            ? effectiveLine1
866	            : effectiveLine1 + " " + effectiveLine2;
867	        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
868	        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
869	        owner.setAddress(composed);
870	    }
871	
872	    /**
873	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
874	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
875	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
876	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
877	     * value, or one that is blank once trimmed, normalizes to an empty string.
878	     *
879	     * @param address the raw address value as submitted, may be {@code null}
880	     * @return the normalized address, or an empty string when none was supplied
881	     */
882	    private String normalizeAddress(String address) {
883	        if (address == null) {
884	            return "";
885	        }
886	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
887	        if (collapsed.isEmpty()) {
888	            return "";
889	        }
890	        String[] tokens = collapsed.split(" ");
891	        StringBuilder normalized = new StringBuilder(collapsed.length());
892	        for (int i = 0; i < tokens.length; i++) {
893	            if (i > 0) {
894	                normalized.append(' ');
895	            }
896	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
897	        }
898	        return normalized.toString();
899	    }
