996	    /**
997	     * Immutable structured audit event emitted alongside the human-readable audit line on a successful
998	     * owner create. It records the create's monotonic {@code seq}, the new owner's id, the owner's
999	     * current primary identifier and its membership level, plus a fixed {@code OWNER_CREATED} marker.
1000	     *
1001	     * <p>The primary identifier is serialized under the {@code memberId} key, matching the owner's
1002	     * unified primary identifier.
1003	     */
1004	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
1005	                                     Integer membershipLevel) {
1006	
1007	        private static final String EVENT = "OWNER_CREATED";
1008	
1009	        /**
1010	         * Renders the event as a compact JSON object
1011	         * {@code {"seq":..,"ownerId":..,"memberId":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
1012	         */
1013	        String toJson() {
1014	            StringBuilder json = new StringBuilder(96);
1015	            json.append('{')
1016	                .append("\"seq\":").append(this.seq)
1017	                .append(",\"ownerId\":").append(this.ownerId)
1018	                .append(",\"memberId\":").append(jsonString(this.memberId))
1019	                .append(",\"membershipLevel\":").append(this.membershipLevel)
1020	                .append(",\"event\":").append(jsonString(EVENT))
1021	                .append('}');
1022	            return json.toString();
1023	        }
1024	
1025	        /**
1026	         * Renders a nullable string as a JSON literal: {@code null} when absent, otherwise a
1027	         * double-quoted, minimally-escaped string.
1028	         */
1029	        private static String jsonString(String value) {
1030	            if (value == null) {
1031	                return "null";
1032	            }
1033	            StringBuilder out = new StringBuilder(value.length() + 2);
1034	            out.append('"');
1035	            for (int i = 0; i < value.length(); i++) {
1036	                char c = value.charAt(i);
1037	                switch (c) {
1038	                    case '"' -> out.append("\\\"");
1039	                    case '\\' -> out.append("\\\\");
1040	                    case '\n' -> out.append("\\n");
1041	                    case '\r' -> out.append("\\r");
1042	                    case '\t' -> out.append("\\t");
1043	                    default -> {
1044	                        if (c < 0x20) {
1045	                            out.append(String.format("\\u%04x", (int) c));
1046	                        } else {
1047	                            out.append(c);
1048	                        }
1049	                    }
1050	                }
1051	            }
1052	            out.append('"');
1053	            return out.toString();
1054	        }
1055	    }
1056	}
