207	    protected String identityKey(Owner owner) {
208	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
209	    }
210	
211	    /**
212	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
213	     * present, otherwise {@code PHONE}.
214	     */
215	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
216	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
217	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
218	    }
219	
220	    /**
221	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
222	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
223	     */
224	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
225	        "NSW", new int[] {2000, 2099},
226	        "VIC", new int[] {3000, 3099},
227	        "QLD", new int[] {4000, 4099});
228	
229	    /**
230	     * Derives the owner's locality (region) from the unified {@code memberId}: it is the REGION
231	     * component of the owner's {@code memberId} ({@code <REGION><FY><HASH8><CHK>}), so the locality
232	     * now moves in lockstep with the identity assigned on create. When no member id has been
233	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
234	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
235	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
236	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
237	     */
238	    protected String locality(Owner owner) {
239	        String region = regionFromMemberId(owner.getMemberId());
240	        if (region != null) {
241	            return region;
242	        }
243	        String fromPostcode = regionFromPostcode(owner.getPostcode());
244	        if (fromPostcode != null) {
245	            return fromPostcode;
246	        }
247	        String city = owner.getCity();
248	        if (city == null) {
249	            return "UNKNOWN";
250	        }
251	        return switch (city) {
252	            case "Sydney" -> "NSW";
253	            case "Melbourne" -> "VIC";
254	            case "Brisbane" -> "QLD";
255	            default -> "UNKNOWN";
256	        };
257	    }
258	
259	    /**
260	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
261	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
262	     */
263	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
264	        "NSW", "Australia/Sydney",
265	        "VIC", "Australia/Melbourne",
266	        "QLD", "Australia/Brisbane");
267	
268	    /**
269	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
270	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
271	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
272	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
273	     */
274	    protected String timezone(Owner owner) {
275	        return REGION_TIMEZONE.get(locality(owner));
276	    }
277	
278	    /**
279	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
280	     * the postcode is absent, not 4 digits, or in no known range.
281	     */
282	    private String regionFromPostcode(String postcode) {
283	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
284	            return null;
285	        }
286	        int value = Integer.parseInt(postcode);
287	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
288	            int[] range = entry.getValue();
289	            if (value >= range[0] && value <= range[1]) {
290	                return entry.getKey();
291	            }
292	        }
293	        return null;
294	    }
295	
296	    /**
297	     * The minimum {@link #membershipLevel(Owner) membership level} at which an owner is a
298	     * {@code PREMIUM} tier for {@link #ownerSegment(Owner) segmentation}; below it the owner is
299	     * {@code STANDARD}.
300	     */
301	    private static final int PREMIUM_TIER_MIN_LEVEL = 3;
302	
303	    /**
304	     * The regions treated as {@code METRO} for {@link #ownerSegment(Owner) segmentation}; any other
305	     * locality (e.g. {@code UNKNOWN}) is {@code REGIONAL}.
306	     */
307	    private static final java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
308	
309	    /**
310	     * Derives the owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>} (one of
311	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
312	     * {@code STANDARD_REGIONAL}). TIER is {@code PREMIUM} when the owner's
313	     * {@link #membershipLevel(Owner) membership level} is {@value #PREMIUM_TIER_MIN_LEVEL} or more,
314	     * otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
315	     * {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD), otherwise
316	     * {@code REGIONAL}.
317	     */
318	    protected OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
319	        String tier = membershipLevel(owner) >= PREMIUM_TIER_MIN_LEVEL ? "PREMIUM" : "STANDARD";
320	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
321	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
322	    }
323	
324	    /**
325	     * The minimum household size (counting the owner itself) that earns household membership
326	     * points.
327	     */
328	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
329	
330	    /**
331	     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
332	     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
333	     * clears this threshold.
334	     */
335	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
336	
337	    /**
338	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
339	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
340	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
341	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
342	     */
343	    protected Integer membershipPoints(Owner owner) {
344	        int points = 0;
345	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
346	        if (hasEmail) {
347	            points += 2;
348	        }
349	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
350	        if (noNamesakes) {
351	            points += 1;
352	        }
353	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
354	            points += 2;
355	        }
356	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
357	            points += 3;
358	        }
359	        return points;
360	    }
361	
362	    /**
363	     * Derives the owner's membership level, capped by their household. The level starts from the
364	     * owner's own {@link #uncappedMembershipLevel(Owner) points-based level} but may not exceed one
365	     * above the current maximum level among the owner's existing household members (other owners
366	     * sharing its {@code householdId}). When the owner has no existing household member no cap
367	     * applies and the points-based level is returned unchanged.
368	     */
369	    protected Integer membershipLevel(Owner owner) {
370	        int level = uncappedMembershipLevel(owner);
371	        OptionalInt maxHouseholdLevel = otherHouseholdMembers(owner)
372	            .mapToInt(this::uncappedMembershipLevel)
373	            .max();
374	        if (maxHouseholdLevel.isEmpty()) {
375	            return level;
376	        }
377	        return Math.min(level, maxHouseholdLevel.getAsInt() + 1);
378	    }
379	
380	    /**
381	     * The owner's points-based membership level, before the household ceiling is applied: level 1
382	     * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more (see
383	     * {@link #membershipPoints(Owner) membership points}). The household members' maximum against
384	     * which {@link #membershipLevel(Owner)} caps is measured with this uncapped value, so mutual
385	     * household members do not recurse into each other's caps.
386	     */
387	    private int uncappedMembershipLevel(Owner owner) {
388	        int points = membershipPoints(owner);
389	        if (points <= 1) {
390	            return 1;
391	        }
392	        if (points <= 3) {
393	            return 2;
394	        }
395	        if (points <= 5) {
396	            return 3;
397	        }
398	        return 4;
399	    }
400	
401	    /**
402	     * The owner's existing household members: every other owner (excluding the owner itself) sharing
403	     * its {@code householdId}. Empty when the owner has no household identifier or is the sole member
404	     * of its household.
405	     */
406	    private Stream<Owner> otherHouseholdMembers(Owner owner) {
407	        String householdId = owner.getHouseholdId();
408	        if (householdId == null) {
409	            return Stream.empty();
410	        }
411	        return this.clinicService.findAllOwners().stream()
412	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
413	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()));
414	    }
415	
416	    /**
417	     * The number of owners in this owner's household — the count of owners (including this one)
418	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
419	     */
420	    private long householdSize(Owner owner) {
421	        String householdId = owner.getHouseholdId();
422	        if (householdId == null) {
423	            return 0;
424	        }
425	        return this.clinicService.findAllOwners().stream()
426	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
427	            .count();
428	    }
429	
430	    /**
431	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
432	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
433	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
434	     * owner without a registration date is treated as having no tenure.
435	     */
436	    private long tenureFiscalYears(Owner owner) {
437	        LocalDate registrationDate = owner.getRegistrationDate();
438	        if (registrationDate == null) {
439	            return 0;
440	        }
441	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
442	    }
443	
444	    /**
445	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
446	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
447	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
448	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
449	     * owner has no registration date.
450	     */
451	    protected Boolean bulkSignupWarning(Owner owner) {
452	        LocalDate registrationDate = owner.getRegistrationDate();
453	        if (registrationDate == null) {
454	            return false;
455	        }
456	        long othersOnDay = this.clinicService.findAllOwners().stream()
457	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
458	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
459	            .count();
460	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
461	    }
462	
463	    /**
464	     * Flags a city approaching its hard capacity limit: {@code true} when this owner's city already
465	     * holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one owners,
466	     * inclusive (excluding the owner itself), so on a create the flag reflects the owners that
467	     * pre-existed it in that city, matching the count the per-city capacity limit is enforced
468	     * against. Cities are compared case-insensitively, as they are for the capacity limit. Returns
469	     * {@code false} when the owner has no city.
470	     */
471	    protected Boolean capacityWarning(Owner owner) {
472	        String city = owner.getCity();
473	        if (city == null) {
474	            return false;
475	        }
476	        long othersInCity = this.clinicService.findAllOwners().stream()
477	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
478	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
479	            .count();
480	        return othersInCity >= CAPACITY_WARNING_THRESHOLD && othersInCity < CITY_CAPACITY;
481	    }
482	
483	    /**
484	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
485	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
486	     * title was supplied (a {@code null} or blank title).
487	     */
488	    protected String salutation(Owner owner) {
489	        String title = owner.getTitle();
490	        String lastName = owner.getLastName();
491	        if (title == null || title.isBlank()) {
492	            return lastName;
493	        }
494	        return title + " " + lastName;
495	    }
496	
497	    /**
498	     * Derives the owner's {@code selfLink}: the canonical link to this owner resource, formatted
499	     * {@code /api/owners/<id>} using the owner's id. Returns {@code null} when the owner has no id.
500	     */
501	    protected String selfLink(Owner owner) {
502	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
503	    }
504	
505	    public abstract Owner toOwner(OwnerDto ownerDto);
506	
507	    @Mapping(target = "id", ignore = true)
508	    @Mapping(target = "pets", ignore = true)
509	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
510	
511	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
512	
513	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
514	
515	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
516	        OwnerPageDto ownerPageDto = new OwnerPageDto();
517	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
518	        ownerPageDto.setPage(ownerPage.getNumber());
519	        ownerPageDto.setSize(ownerPage.getSize());
520	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
521	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
522	        return ownerPageDto;
523	    }
524	}
